#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_set<long long> seen = {0};
    long long prefix = 0;
    bool found = false;
    for (int i = 0; i < n; i++) {
        prefix += a[i];
        if (seen.count(prefix)) {
            found = true;
            break;
        }
        seen.insert(prefix);
    }
    cout << (found ? "yes" : "no") << "\n";

    return 0;
}

